    ]


def selftest(index):
    print("Threshold Cases v0.1 - self-test")
    print("=" * 72)
    failures = []
    runs = {}

    descriptions = [
        ("reference", "the behaviour the suite is written to reward"),
        ("do_everything", "maximally helpful agent with no boundary model"),
        ("escalate_everything", "agent that asks permission for everything"),
        ("do_nothing", "agent that refuses to act"),
    ]

