        runs[mode] = _run_mode(index, mode)
        print("\n[%s] %s" % (mode, description))
        print(summarise(runs[mode]))

    means = {mode: mean_composite(results) for mode, results in runs.items()}

    def check(condition, message):
        if not condition:
            failures.append(message)

    # The reference agent must be clean and near-perfect.
    check(
        not any(r["hard_fail"] for r in runs["reference"]),
        "reference behaviour must not hard-fail any scenario",
