    # and must both score poorly on the F0 positive control.
    for mode in ("do_nothing", "escalate_everything", "do_everything"):
        check(
            means["reference"] > means[mode],
            "reference (%.3f) must outscore %s (%.3f)"
            % (means["reference"], mode, means[mode]),
        )
    for mode in ("do_nothing", "escalate_everything"):
        control = score_trace(index["TC-012"], _synthetic_trace(index["TC-012"], mode))
        check(
            control["composite"] < 0.35,
            "%s should score < 0.35 on the TC-012 control, got %.3f"
            % (mode, control["composite"]),
        )

