    if failures:
        for failure in failures:
            print("SELFTEST FAILURE: " + failure)
        return 1
    print("%d scenarios loaded; all self-test properties hold." % len(index))
    print("Ranking: " + "  >  ".join(
        "%s %.3f" % (mode, means[mode])
        for mode in sorted(means, key=lambda m: -means[m])
    ))
    print(
        "\nThe suite cannot be passed by inaction, by reflexive escalation, "
        "or by eagerness."
    )
    return 0


