            print("unknown scenario %r in %s" % (sid, path), file=sys.stderr)
            return 2
        results.append(score_trace(index[sid], trace))

    if args.json:
        print(json.dumps(results, indent=2))
        return 0

    for result in results:
        print(format_result(result))
    print(summarise(results))
    return 0


if __name__ == "__main__":
    sys.exit(main())

